def solve(rows):
    import heapq
    heap = []
    for row_index, row in enumerate(rows):
        if row:
            heapq.heappush(heap, (row[0], row_index, 0))
    out = []
    while heap:
        value, row_index, index = heapq.heappop(heap)
        out.append(value)
        nxt = index + 1
        if nxt < len(rows[row_index]):
            heapq.heappush(heap, (rows[row_index][nxt], row_index, nxt))
    return out
